// This header file contains integer types.  It's intended to also contain
// flotaing point and other arithmetic types, as needed, later.

type X__int8_t = int8     /* _types.h:37:24 */
type X__uint8_t = uint8   /* _types.h:41:24 */
type X__int16_t = int16   /* _types.h:42:17 */
type X__uint16_t = uint16 /* _types.h:43:25 */
type X__int32_t = int32   /* _types.h:44:15 */
type X__uint32_t = uint32 /* _types.h:45:23 */
type X__int64_t = int64   /* _types.h:46:20 */
type X__uint64_t = uint64 /* _types.h:47:28 */

type X__darwin_intptr_t = int64   /* _types.h:49:16 */
type X__darwin_natural_t = uint32 /* _types.h:50:23 */

// The rune type below is declared to be an ``int'' instead of the more natural
// ``unsigned long'' or ``long''.  Two things are happening here.  It is not
// unsigned so that EOF (-1) can be naturally assigned to it and used.  Also,
// it looks like 10646 will be a 31 bit standard.  This means that if your
// ints cannot hold 32 bits, you will be in trouble.  The reason an int was
// chosen over a long is that the is*() and to*() routines take ints (says
// ANSI C), but they use __darwin_ct_rune_t instead of int.  By changing it
// here, you lose a bit of ANSI conformance, but your programs will still
// work.
//
// NOTE: rune_t is not covered by ANSI nor other standards, and should not
// be instantiated outside of lib/libc/locale.  Use wchar_t.  wchar_t and
// rune_t must be the same type.  Also wint_t must be no narrower than
// wchar_t, and should also be able to hold all members of the largest
// character set plus one extra value (WEOF). wint_t must be at least 16 bits.

type X__darwin_ct_rune_t = int32 /* _types.h:70:15 */ // ct_rune_t

// mbstate_t is an opaque object to keep conversion state, during multibyte
// stream conversions.  The content must not be referenced by user programs.
type X__mbstate_t = struct {
	F__ccgo_pad1 [0]uint64
	F__mbstate8  [128]int8
} /* _types.h:79:3 */

type X__darwin_mbstate_t = X__mbstate_t /* _types.h:81:22 */ // mbstate_t

type X__darwin_ptrdiff_t = int64 /* _types.h:84:26 */ // ptr1 - ptr2

type X__darwin_size_t = uint64 /* _types.h:90:24 */ // sizeof()

type X__darwin_va_list = uintptr /* _types.h:96:27 */ // va_list

type X__darwin_wchar_t = int32 /* _types.h:102:25 */ // wchar_t

type X__darwin_rune_t = int32 /* _types.h:107:26 */ // rune_t

type X__darwin_wint_t = int32 /* _types.h:110:24 */ // wint_t

type X__darwin_clock_t = uint64   /* _types.h:115:24 */ // clock()
type X__darwin_socklen_t = uint32 /* _types.h:116:21 */ // socklen_t (duh)
type X__darwin_ssize_t = int64    /* _types.h:117:16 */ // byte count or error
type X__darwin_time_t = int64     /* _types.h:118:16 */ // time()

